"""Grid binning of sonar soundings at multiple resolutions.

For every resolution ``r`` the rectangle ``(xmin, ymin)``-
``(xmax, ymax)`` is divided into ``nx = (xmax - xmin) / r`` columns
and ``ny = (ymax - ymin) / r`` rows, both integral. A cell includes
its left/bottom edges and excludes its right/top edges; a point on the
maximum edge is assigned to the last column/row. Cells are ordered by
``y`` then ``x`` (``y`` primary), and the depths falling in each cell
are averaged with ``math.fsum`` in point input order.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["build"]

_FIELDS = ("x", "y", "d")


def build(points, bounds, resolutions):
    """Bin points into regular grids at several resolutions.

    ``points`` is a non-empty list/tuple of three-element lists/tuples
    ``(x, y, d)``; ``bounds`` is a four-element list/tuple
    ``(xmin, ymin, xmax, ymax)``; ``resolutions`` is a list/tuple of at
    least two strictly increasing values. Every value must be a finite
    non-bool int/float. In addition ``d >= 0``, ``xmin < xmax``,
    ``ymin < ymax`` and each resolution ``r > 0``; every point must lie
    within the closed bounds and both ``(xmax - xmin) / r`` and
    ``(ymax - ymin) / r`` must be integral Python floats.

    For each resolution ``r``, ``nx``/``ny`` are the two quotients as
    ints. Cells include the left/bottom edges and exclude the
    right/top edges, except that a point on the maximum edge joins the
    last column/row. Cells are expanded by ``y`` then ``x``; the depths
    of a cell are averaged as ``math.fsum`` over input order divided by
    their count.

    Validation order (first error wins): the three containers, point
    non-emptiness, each point (container, length), the bounds length,
    the resolutions minimum length, then the numeric types and
    finiteness of points/bounds/resolutions in that order; then
    ``d >= 0`` per point, ``xmin < xmax``, ``ymin < ymax``, the strict
    increase and positivity of resolutions, the closed-bounds
    containment per point, and finally per resolution the integral
    width/height quotients. Container and value type errors (including
    bool) raise ``TypeError``; all other constraint errors raise
    ``ValueError``. Point errors are prefixed with ``"points[i]: "``.

    Returns a tuple in resolutions order; each layer is
    ``(r, nx, ny, cells)`` and each cell is ``(count, mean)`` with empty
    cells fixed as ``(0, None)``. ``nx``/``ny``/``count`` are ints;
    ``r``/``mean`` are floats rounded to 6 decimals with
    ``round(float(v), 6)`` (negative zero normalized to ``0.0``). All
    binning uses the unrounded input values; inputs are not modified.
    """
    for name, value in (
        ("points", points),
        ("bounds", bounds),
        ("resolutions", resolutions),
    ):
        if not isinstance(value, (list, tuple)):
            raise TypeError(f"{name} must be a list or tuple")

    if len(points) == 0:
        raise ValueError("points must be non-empty")
    for i in range(len(points)):
        prefix = f"points[{i}]: "
        if not isinstance(points[i], (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(points[i]) != 3:
            raise ValueError(prefix + "must have 3 elements")
    if len(bounds) != 4:
        raise ValueError("bounds must have 4 elements")
    if len(resolutions) < 2:
        raise ValueError("resolutions must have at least 2 elements")

    for i in range(len(points)):
        prefix = f"points[{i}]: "
        for name, value in zip(_FIELDS, points[i]):
            if not _is_real_number(value):
                raise TypeError(prefix + f"{name} must be a non-bool int or float")
            if not math.isfinite(value):
                raise ValueError(prefix + f"{name} must be finite")
    for value in bounds:
        if not _is_real_number(value):
            raise TypeError("bounds elements must be non-bool int or float")
    for value in bounds:
        if not math.isfinite(value):
            raise ValueError("bounds elements must be finite")
    for value in resolutions:
        if not _is_real_number(value):
            raise TypeError("resolutions elements must be non-bool int or float")
    for value in resolutions:
        if not math.isfinite(value):
            raise ValueError("resolutions elements must be finite")

    for i in range(len(points)):
        if not points[i][2] >= 0:
            raise ValueError(f"points[{i}]: d must be >= 0")

    xmin, ymin, xmax, ymax = bounds
    if not xmin < xmax:
        raise ValueError("xmin must be < xmax")
    if not ymin < ymax:
        raise ValueError("ymin must be < ymax")

    for k in range(len(resolutions) - 1):
        if not resolutions[k] < resolutions[k + 1]:
            raise ValueError("resolutions must be strictly increasing")
    for k in range(len(resolutions)):
        if not resolutions[k] > 0:
            raise ValueError(f"resolutions[{k}] must be > 0")

    for i in range(len(points)):
        x, y, _ = points[i]
        if not (xmin <= x <= xmax and ymin <= y <= ymax):
            raise ValueError(f"points[{i}]: point must be within bounds")

    width = xmax - xmin
    height = ymax - ymin
    grids = []
    for k in range(len(resolutions)):
        r = resolutions[k]
        qx = width / r
        qy = height / r
        if not qx.is_integer():
            raise ValueError(f"width must be divisible by resolutions[{k}]")
        if not qy.is_integer():
            raise ValueError(f"height must be divisible by resolutions[{k}]")
        grids.append((r, int(qx), int(qy)))

    layers = []
    for r, nx, ny in grids:
        buckets = [[] for _ in range(ny * nx)]
        for x, y, d in points:
            ix = math.floor((x - xmin) / r)
            iy = math.floor((y - ymin) / r)
            if ix == nx:
                ix = nx - 1
            if iy == ny:
                iy = ny - 1
            buckets[iy * nx + ix].append(d)

        cells = []
        for bucket in buckets:
            count = len(bucket)
            if count == 0:
                cells.append((0, None))
                continue
            mean = round(float(math.fsum(bucket) / count), 6)
            if mean == 0:
                mean = 0.0
            cells.append((count, mean))

        rr = round(float(r), 6)
        if rr == 0:
            rr = 0.0
        layers.append((rr, nx, ny, tuple(cells)))
    return tuple(layers)

"""Terrain analysis of a gridded bathymetric surface.

Given a regular grid of cell mean depths (as produced by
:func:`ocean_sonar.grid.build`), derive per-cell slope and roughness.
Slope is the gradient angle in degrees from the four direct neighbours;
roughness is the ``max - min`` spread of the non-empty means in the
boundary-clipped 3x3 neighbourhood.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["analyze", "analyze_layers"]


def _round6(value):
    result = round(float(value), 6)
    if result == 0:
        result = 0.0
    return result


def analyze(r, nx, ny, cells):
    """Compute per-cell slope and roughness for a regular depth grid.

    ``r`` is the cell size, a finite non-bool int/float with ``r > 0``.
    ``nx``/``ny`` are non-bool positive ints. ``cells`` is a list/tuple
    of length ``nx * ny`` ordered by ``y`` then ``x``; each item is a
    two-element list/tuple ``(count, mean)`` where ``count`` is a
    non-bool non-negative int, ``mean`` is exactly ``None`` when
    ``count == 0`` and a finite non-bool int/float ``>= 0`` otherwise.

    For a non-empty cell, roughness is ``max - min`` over the non-empty
    means of the 3x3 neighbourhood clipped to the grid bounds. With
    left/right/down/up neighbour means ``L``/``R``/``D``/``U`` all
    present and non-empty, slope is
    ``degrees(atan(hypot((R - L) / (2 * r), (U - D) / (2 * r))))``;
    otherwise slope is ``None``. Empty cells are fixed as
    ``(None, None)``.

    Validation follows the signature parameter order and then grid
    order, stopping at the first error: type mismatches (including
    bool) raise ``TypeError``, all other constraint errors raise
    ``ValueError``. Cell errors are prefixed with ``"cells[i]: "``.

    Returns a tuple in the same order and length as ``cells`` of
    ``(slope, roughness)`` pairs; non-``None`` values are rounded with
    ``round(float(v), 6)`` (negative zero normalized to ``0.0``). All
    computation uses the unrounded means; inputs are not modified.
    """
    if not _is_real_number(r):
        raise TypeError("r must be a non-bool int or float")
    if not math.isfinite(r):
        raise ValueError("r must be finite")
    if not r > 0:
        raise ValueError("r must be > 0")

    for name, value in (("nx", nx), ("ny", ny)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be a non-bool int")
        if not value > 0:
            raise ValueError(f"{name} must be > 0")

    if not isinstance(cells, (list, tuple)):
        raise TypeError("cells must be a list or tuple")
    if len(cells) != nx * ny:
        raise ValueError("cells must have nx * ny elements")

    for i in range(len(cells)):
        prefix = f"cells[{i}]: "
        cell = cells[i]
        if not isinstance(cell, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(cell) != 2:
            raise ValueError(prefix + "must have 2 elements")
        count, mean = cell
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError(prefix + "count must be a non-bool int")
        if not count >= 0:
            raise ValueError(prefix + "count must be >= 0")
        if count == 0:
            if mean is not None:
                raise ValueError(prefix + "mean must be None when count is 0")
        else:
            if not _is_real_number(mean):
                raise TypeError(prefix + "mean must be a non-bool int or float")
            if not math.isfinite(mean):
                raise ValueError(prefix + "mean must be finite")
            if not mean >= 0:
                raise ValueError(prefix + "mean must be >= 0")

    means = [cell[1] if cell[0] > 0 else None for cell in cells]

    def mean_at(ix, iy):
        if 0 <= ix < nx and 0 <= iy < ny:
            return means[iy * nx + ix]
        return None

    result = []
    for iy in range(ny):
        for ix in range(nx):
            center = means[iy * nx + ix]
            if center is None:
                result.append((None, None))
                continue

            low = high = center
            for jy in range(max(0, iy - 1), min(ny, iy + 2)):
                for jx in range(max(0, ix - 1), min(nx, ix + 2)):
                    value = means[jy * nx + jx]
                    if value is None:
                        continue
                    if value < low:
                        low = value
                    if value > high:
                        high = value
            roughness = _round6(high - low)

            left = mean_at(ix - 1, iy)
            right = mean_at(ix + 1, iy)
            down = mean_at(ix, iy - 1)
            up = mean_at(ix, iy + 1)
            if None in (left, right, down, up):
                slope = None
            else:
                slope = _round6(
                    math.degrees(
                        math.atan(
                            math.hypot(
                                (right - left) / (2 * r),
                                (up - down) / (2 * r),
                            )
                        )
                    )
                )
            result.append((slope, roughness))
    return tuple(result)


def analyze_layers(layers):
    """Analyze several depth grids in one call.

    ``layers`` is a non-empty list/tuple whose items, in input order,
    are four-element list/tuples ``(r, nx, ny, cells)`` with the same
    constraints as the parameters of :func:`analyze`.

    Validation order: the outer container, non-emptiness, then per
    layer ``i`` its container, length, ``r``, ``nx``, ``ny``, the
    ``cells`` container and length, and finally per cell ``j`` its
    container, length, ``count`` and ``mean``; the first error stops
    the call. Container/type mismatches (including bool) raise
    ``TypeError``, all other constraint errors raise ``ValueError``.
    Errors are prefixed with ``"layers[i]: "`` or
    ``"layers[i].cells[j]: "``.

    Each layer is passed to :func:`analyze` unchanged. Returns a tuple
    in input order of dicts with keys ``resolution``, ``nx``, ``ny``,
    ``analysis`` (in that order): ``resolution`` is
    ``round(float(r), 6)`` (negative zero normalized to ``0.0``),
    ``nx``/``ny`` are ints and ``analysis`` is the tuple returned by
    :func:`analyze` as-is. Inputs are not modified.
    """
    if not isinstance(layers, (list, tuple)):
        raise TypeError("layers must be a list or tuple")
    if len(layers) == 0:
        raise ValueError("layers must not be empty")

    results = []
    for i in range(len(layers)):
        prefix = f"layers[{i}]: "
        layer = layers[i]
        if not isinstance(layer, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(layer) != 4:
            raise ValueError(prefix + "must have 4 elements")
        r, nx, ny, cells = layer

        if not _is_real_number(r):
            raise TypeError(prefix + "r must be a non-bool int or float")
        if not math.isfinite(r):
            raise ValueError(prefix + "r must be finite")
        if not r > 0:
            raise ValueError(prefix + "r must be > 0")

        for name, value in (("nx", nx), ("ny", ny)):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(prefix + f"{name} must be a non-bool int")
            if not value > 0:
                raise ValueError(prefix + f"{name} must be > 0")

        if not isinstance(cells, (list, tuple)):
            raise TypeError(prefix + "cells must be a list or tuple")
        if len(cells) != nx * ny:
            raise ValueError(prefix + "cells must have nx * ny elements")

        for j in range(len(cells)):
            cell_prefix = f"layers[{i}].cells[{j}]: "
            cell = cells[j]
            if not isinstance(cell, (list, tuple)):
                raise TypeError(cell_prefix + "must be a list or tuple")
            if len(cell) != 2:
                raise ValueError(cell_prefix + "must have 2 elements")
            count, mean = cell
            if not isinstance(count, int) or isinstance(count, bool):
                raise TypeError(cell_prefix + "count must be a non-bool int")
            if not count >= 0:
                raise ValueError(cell_prefix + "count must be >= 0")
            if count == 0:
                if mean is not None:
                    raise ValueError(
                        cell_prefix + "mean must be None when count is 0"
                    )
            else:
                if not _is_real_number(mean):
                    raise TypeError(
                        cell_prefix + "mean must be a non-bool int or float"
                    )
                if not math.isfinite(mean):
                    raise ValueError(cell_prefix + "mean must be finite")
                if not mean >= 0:
                    raise ValueError(cell_prefix + "mean must be >= 0")

        results.append(
            {
                "resolution": _round6(r),
                "nx": int(nx),
                "ny": int(ny),
                "analysis": analyze(r, nx, ny, cells),
            }
        )
    return tuple(results)

"""Seabed substrate classification from slope/roughness analysis grids.

Each layer pairs a regular per-cell ``(slope, roughness)`` analysis grid
(as produced by :func:`ocean_sonar.terrain.analyze`) with its cell size
and classifies every cell into a substrate class by thresholding slope
and roughness.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["classify"]

_CLASSES = ("mud", "sand", "gravel", "rock")


def _round6(value):
    result = round(float(value), 6)
    if result == 0:
        result = 0.0
    return result


def _check_limit(name, value):
    if not _is_real_number(value):
        raise TypeError(f"{name} must be a non-bool int or float")
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    if not value > 0:
        raise ValueError(f"{name} must be > 0")


def classify(layers, slope_limit=5.0, roughness_limit=1.0):
    """Classify analysis grids into seabed substrate classes.

    ``layers`` is a non-empty list/tuple of four-element list/tuples
    ``(r, nx, ny, analysis)``: ``r`` is the cell size, a finite non-bool
    int/float with ``r > 0``; ``nx``/``ny`` are non-bool positive ints;
    ``analysis`` is a list/tuple of length ``nx * ny`` ordered by ``y``
    then ``x``. Each cell is a two-element list/tuple ``(slope,
    roughness)``; ``(None, None)``, ``(None, q)`` and ``(p, q)`` are
    legal (``None`` marks unknown), ``(p, None)`` with non-``None``
    ``p`` is not. Non-``None`` values must be finite non-bool
    int/float ``>= 0``. ``slope_limit``/``roughness_limit`` are finite
    non-bool int/float ``> 0``.

    A cell with ``slope`` equal to ``None`` is ``unknown``. Otherwise
    the bit pair ``(slope > slope_limit, roughness > roughness_limit)``
    selects the class: ``00`` mud, ``01`` sand, ``10`` gravel,
    ``11`` rock.

    Validation order: ``layers`` container, non-emptiness, then per
    layer (container, 4 elements, ``r``, ``nx``, ``ny``, ``analysis``
    container/length), then per cell (container, 2 elements, ``slope``,
    ``roughness``), then ``slope_limit``, then ``roughness_limit``;
    checking stops at the first error. Type mismatches (including bool)
    raise ``TypeError``, all other constraint errors raise
    ``ValueError``. Layer errors are prefixed with ``"layers[i]: "``
    and cell errors with ``"layers[i].analysis[j]: "``.

    Returns a tuple with one dict per layer, keys in order
    ``resolution``, ``nx``, ``ny``, ``classes``, ``counts``.
    ``resolution`` is ``round(float(r), 6)`` (negative zero normalized
    to ``0.0``); ``classes`` is a tuple of class name strings in grid
    order (``y`` then ``x``); ``counts`` maps ``unknown``, ``mud``,
    ``sand``, ``gravel``, ``rock`` (in that key order) to int counts.
    Inputs are not modified.
    """
    if not isinstance(layers, (list, tuple)):
        raise TypeError("layers must be a list or tuple")
    if len(layers) == 0:
        raise ValueError("layers must be non-empty")

    for i in range(len(layers)):
        prefix = f"layers[{i}]: "
        layer = layers[i]
        if not isinstance(layer, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(layer) != 4:
            raise ValueError(prefix + "must have 4 elements")
        r, nx, ny, analysis = layer
        if not _is_real_number(r):
            raise TypeError(prefix + "r must be a non-bool int or float")
        if not math.isfinite(r):
            raise ValueError(prefix + "r must be finite")
        if not r > 0:
            raise ValueError(prefix + "r must be > 0")
        for name, value in (("nx", nx), ("ny", ny)):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(prefix + f"{name} must be a non-bool int")
            if not value > 0:
                raise ValueError(prefix + f"{name} must be > 0")
        if not isinstance(analysis, (list, tuple)):
            raise TypeError(prefix + "analysis must be a list or tuple")
        if len(analysis) != nx * ny:
            raise ValueError(prefix + "analysis must have nx * ny elements")
        for j in range(len(analysis)):
            cell_prefix = f"layers[{i}].analysis[{j}]: "
            cell = analysis[j]
            if not isinstance(cell, (list, tuple)):
                raise TypeError(cell_prefix + "must be a list or tuple")
            if len(cell) != 2:
                raise ValueError(cell_prefix + "must have 2 elements")
            slope, roughness = cell
            if slope is not None:
                if not _is_real_number(slope):
                    raise TypeError(
                        cell_prefix + "slope must be a non-bool int or float"
                    )
                if not math.isfinite(slope):
                    raise ValueError(cell_prefix + "slope must be finite")
                if not slope >= 0:
                    raise ValueError(cell_prefix + "slope must be >= 0")
            if roughness is None:
                if slope is not None:
                    raise ValueError(
                        cell_prefix
                        + "roughness must not be None when slope is not None"
                    )
            else:
                if not _is_real_number(roughness):
                    raise TypeError(
                        cell_prefix + "roughness must be a non-bool int or float"
                    )
                if not math.isfinite(roughness):
                    raise ValueError(cell_prefix + "roughness must be finite")
                if not roughness >= 0:
                    raise ValueError(cell_prefix + "roughness must be >= 0")

    _check_limit("slope_limit", slope_limit)
    _check_limit("roughness_limit", roughness_limit)

    result = []
    for layer in layers:
        r, nx, ny, analysis = layer
        classes = []
        counts = {"unknown": 0, "mud": 0, "sand": 0, "gravel": 0, "rock": 0}
        for cell in analysis:
            slope, roughness = cell
            if slope is None:
                name = "unknown"
            else:
                index = (
                    2 * (slope > slope_limit) + (roughness > roughness_limit)
                )
                name = _CLASSES[index]
            classes.append(name)
            counts[name] += 1
        result.append(
            {
                "resolution": _round6(r),
                "nx": nx,
                "ny": ny,
                "classes": tuple(classes),
                "counts": counts,
            }
        )
    return tuple(result)

"""Quality assessment of gridded terrain-analysis layers.

Given per-layer ``(r, nx, ny, analysis)`` descriptions where each
analysis cell is a ``(slope, roughness)`` pair as produced by
:func:`ocean_sonar.terrain.analyze`, summarize coverage and the counts
of cells whose slope/roughness strictly exceed the given limits.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["assess"]


def _round6(value):
    result = round(float(value), 6)
    if result == 0:
        result = 0.0
    return result


def assess(layers, slope_limit=5.0, roughness_limit=1.0):
    """Assess coverage and limit exceedance per terrain layer.

    ``layers`` is a non-empty list/tuple of ``(r, nx, ny, analysis)``
    items: ``r`` is a finite non-bool int/float ``> 0``; ``nx``/``ny``
    are non-bool positive ints; ``analysis`` is a list/tuple of length
    ``nx * ny`` whose items are two-element list/tuples
    ``(slope, roughness)``. A cell is either exactly ``(None, None)``
    (empty), or ``slope`` is ``None`` or a finite non-bool int/float
    ``>= 0`` and ``roughness`` is a finite non-bool int/float ``>= 0``.
    ``slope_limit``/``roughness_limit`` are finite non-bool int/float
    values ``> 0``.

    Validation follows the signature parameter order, then layer and
    cell index order, then field order, stopping at the first error:
    type mismatches (including bool) raise ``TypeError``, all other
    constraint errors raise ``ValueError``. Layer errors are prefixed
    with ``"layers[i]: "`` and cell errors with
    ``"layers[i].analysis[j]: "``.

    Returns a tuple in the same order as ``layers``; each item is a
    dict with keys ``resolution, total, valid, coverage,
    slope_exceed, roughness_exceed``. ``total`` is ``nx * ny``,
    ``valid`` counts non-empty cells and ``coverage`` is
    ``valid / total``. Exceedance counts use strict ``>`` and ignore
    ``None``. Counts are ints; the other values are
    ``round(float(v), 6)`` (negative zero normalized to ``0.0``).
    Inputs are not modified.
    """
    if not isinstance(layers, (list, tuple)):
        raise TypeError("layers must be a list or tuple")
    if len(layers) == 0:
        raise ValueError("layers must be non-empty")

    for i in range(len(layers)):
        prefix = f"layers[{i}]: "
        layer = layers[i]
        if not isinstance(layer, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(layer) != 4:
            raise ValueError(prefix + "must have 4 elements")
        r, nx, ny, analysis = layer

        if not _is_real_number(r):
            raise TypeError(prefix + "r must be a non-bool int or float")
        if not math.isfinite(r):
            raise ValueError(prefix + "r must be finite")
        if not r > 0:
            raise ValueError(prefix + "r must be > 0")

        for name, value in (("nx", nx), ("ny", ny)):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(prefix + f"{name} must be a non-bool int")
            if not value > 0:
                raise ValueError(prefix + f"{name} must be > 0")

        if not isinstance(analysis, (list, tuple)):
            raise TypeError(prefix + "analysis must be a list or tuple")
        if len(analysis) != nx * ny:
            raise ValueError(prefix + "analysis must have nx * ny elements")

        for j in range(len(analysis)):
            cell_prefix = f"layers[{i}].analysis[{j}]: "
            cell = analysis[j]
            if not isinstance(cell, (list, tuple)):
                raise TypeError(cell_prefix + "must be a list or tuple")
            if len(cell) != 2:
                raise ValueError(cell_prefix + "must have 2 elements")
            slope, roughness = cell
            if slope is None and roughness is None:
                continue
            if slope is not None:
                if not _is_real_number(slope):
                    raise TypeError(
                        cell_prefix + "slope must be None or a non-bool int or float"
                    )
                if not math.isfinite(slope):
                    raise ValueError(cell_prefix + "slope must be finite")
                if not slope >= 0:
                    raise ValueError(cell_prefix + "slope must be >= 0")
            if not _is_real_number(roughness):
                raise TypeError(
                    cell_prefix + "roughness must be a non-bool int or float"
                )
            if not math.isfinite(roughness):
                raise ValueError(cell_prefix + "roughness must be finite")
            if not roughness >= 0:
                raise ValueError(cell_prefix + "roughness must be >= 0")

    for name, value in (("slope_limit", slope_limit), ("roughness_limit", roughness_limit)):
        if not _is_real_number(value):
            raise TypeError(f"{name} must be a non-bool int or float")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
        if not value > 0:
            raise ValueError(f"{name} must be > 0")

    result = []
    for r, nx, ny, analysis in layers:
        total = nx * ny
        valid = 0
        slope_exceed = 0
        roughness_exceed = 0
        for slope, roughness in analysis:
            if slope is None and roughness is None:
                continue
            valid += 1
            if slope is not None and slope > slope_limit:
                slope_exceed += 1
            if roughness > roughness_limit:
                roughness_exceed += 1
        result.append(
            {
                "resolution": _round6(r),
                "total": total,
                "valid": valid,
                "coverage": _round6(valid / total),
                "slope_exceed": slope_exceed,
                "roughness_exceed": roughness_exceed,
            }
        )
    return tuple(result)
